class Solution {
public:
    int consecutiveNumbersSum(int n) {
        int ans = 0;
        for (long long k = 1; k * (k - 1) / 2 < n; k++) {
            if ((n - k * (k - 1) / 2) % k == 0) ans++;
        }
        return ans;
    }
};

class Solution {
