        }
        return ans;
    }
}

var consecutiveNumbersSum = function(n) {
    let ans = 0;
    let k = 1;
    while (k * (k - 1) / 2 < n) {
        if ((n - k * (k - 1) / 2) % k === 0) ans++;
        k++;
    }
    return ans;
};
